package org.scrivo.highlight.languages;

import org.scrivo.highlight.Hljs;
import org.scrivo.highlight.LanguageDefinition;
import org.scrivo.highlight.Mode;

/**
 * Language: Shell Session
 * Requires: bash.js
 * Author: TSUYUSATO Kitsune &lt;make.just.on&#64;gmail.com&gt;
 * Category: common
 * Audit: 2020
 */
public final class Shell implements LanguageDefinition {

	public static final String ID = "shell";

	@Override
	public Mode define(Hljs hljs) {
		return new Mode()
			.name("Shell Session")
			.aliases("console")
			.contains(
				new Mode()
					.className("meta")
					// We cannot add \s (spaces) in the regular expression otherwise it will be too broad and produce unexpected result.
					// For instance, in the following example, it would match "echo /path/to/home >" as a prompt:
					// echo /path/to/home > t.exe
					.begin("^\\s{0,3}[/~\\w\\d[\\]()@-]*[>%$#]")
					.starts(new Mode()
						.end("[^\\\\](?=\\s*$)")
						.subLanguage("bash")));
	}
}
